import{y as e,b as o,c as d,X as r}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const m=JSON.parse('{"title":"Contract Authority","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/CONTRACT_AUTHORITY.md","filePath":"contracts/CONTRACT_AUTHORITY.md","lastUpdated":1771753292000}'),a={name:"contracts/CONTRACT_AUTHORITY.md"};function n(i,t,c,s,l,u){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="contract-authority" tabindex="-1">Contract Authority <a class="header-anchor" href="#contract-authority" aria-label="Permalink to &quot;Contract Authority&quot;">​</a></h1><p>undefined<strong>Status:</strong> Authoritative undefined<strong>Date:</strong> 2026-02-14 undefined<strong>Scope:</strong> Structured output contracts for thegent orchestration</p><hr><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to &quot;1. Purpose&quot;">​</a></h2><p>This document is the <strong>single source of truth</strong> for structured output contracts used by thegent. All agent outputs, XML protocols, and provider-specific formats normalize to the canonical schema defined here.</p><hr><h2 id="_2-contract-registry" tabindex="-1">2. Contract Registry <a class="header-anchor" href="#_2-contract-registry" aria-label="Permalink to &quot;2. Contract Registry&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Contract ID</th><th>Version</th><th>Description</th><th>Compatibility</th></tr></thead><tbody><tr><td>csm</td><td>csm-v1</td><td>Canonical Structured Message: unified schema</td><td>task-tool-18, zen-rich-v1</td></tr><tr><td>task-tool</td><td>task-tool-18</td><td>Task-tool 18-tag XML (snake_case)</td><td>csm-v1</td></tr><tr><td>zen</td><td>zen-rich-v1</td><td>Zen rich protocol (status, progress, actions, files)</td><td>csm-v1</td></tr></tbody></table><hr><h2 id="_3-canonical-schema-csm-v1" tabindex="-1">3. Canonical Schema (CSM v1) <a class="header-anchor" href="#_3-canonical-schema-csm-v1" aria-label="Permalink to &quot;3. Canonical Schema (CSM v1)&quot;">​</a></h2><p>All agent outputs normalize to <code>CanonicalStructuredMessage</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td>task_id</td><td>str</td><td>No</td><td>Task identifier</td></tr><tr><td>run_id</td><td>str</td><td>No</td><td>Run correlation ID</td></tr><tr><td>chunk_id</td><td>str</td><td>No</td><td>Chunk identifier</td></tr><tr><td>status</td><td>enum</td><td>Yes</td><td>pending, in_progress, completed, failed, blocked, cancelled</td></tr><tr><td>phase</td><td>enum</td><td>No</td><td>planner, operator, reviewer, unknown</td></tr><tr><td>progress</td><td>float</td><td>No</td><td>0.0–1.0</td></tr><tr><td>objective</td><td>str</td><td>No</td><td>Task objective</td></tr><tr><td>summary</td><td>str</td><td>No</td><td>Condensed summary</td></tr><tr><td>actions_completed</td><td>list[str]</td><td>No</td><td>Completed action list</td></tr><tr><td>issues</td><td>list[str]</td><td>No</td><td>Issues encountered</td></tr><tr><td>next_steps</td><td>list[str]</td><td>No</td><td>Recommended next steps</td></tr><tr><td>evidence_set_hash</td><td>str</td><td>No</td><td>Governance evidence hash</td></tr><tr><td>policy_gate_id</td><td>str</td><td>No</td><td>Policy gate identifier</td></tr><tr><td>decision_reason_code</td><td>str</td><td>No</td><td>Decision rationale code</td></tr><tr><td>schema_version</td><td>str</td><td>Yes</td><td>Always &quot;csm-v1&quot;</td></tr><tr><td>source_contract</td><td>str</td><td>No</td><td>Original contract (task-tool-18, zen-rich-v1, etc.)</td></tr></tbody></table><hr><h2 id="_4-versioning-policy" tabindex="-1">4. Versioning Policy <a class="header-anchor" href="#_4-versioning-policy" aria-label="Permalink to &quot;4. Versioning Policy&quot;">​</a></h2><ul><li>undefined<strong>contract_id</strong>: Logical contract (csm, task-tool, zen).</li><li>undefined<strong>version</strong>: Semantic version string (e.g. csm-v1, task-tool-18).</li><li>undefined<strong>compatible_with</strong>: Versions that can be normalized to this contract.</li><li>undefined<strong>deprecated</strong>: If true, do not use for new integrations.</li></ul><p>Migration: Use dual-read/dual-write windows when upgrading. Never remove a version without a deprecation period. See <code>docs/contracts/UPGRADE_PLAYBOOK.md</code> for upgrade, canary, and rollback procedures.</p><hr><h2 id="_5-adapter-contract" tabindex="-1">5. Adapter Contract <a class="header-anchor" href="#_5-adapter-contract" aria-label="Permalink to &quot;5. Adapter Contract&quot;">​</a></h2><p>Provider adapters implement <code>OutputAdapter</code>:</p><ul><li><code>provider</code>: Provider identifier (copilot, gemini, codex, claude, etc.)</li><li><code>normalize(raw, context) -&gt; AdapterResult</code>: Convert raw output to CSM</li></ul><p>Adapters must:</p><ul><li>Return <code>AdapterResult</code> with <code>csm</code> and <code>confidence</code> (0.0–1.0).</li><li>Populate <code>parse_errors</code> on partial failure.</li><li>Set <code>source_contract</code> when known.</li></ul><hr><h2 id="_6-implementation-location" tabindex="-1">6. Implementation Location <a class="header-anchor" href="#_6-implementation-location" aria-label="Permalink to &quot;6. Implementation Location&quot;">​</a></h2><ul><li>undefined<strong>Registry</strong>: <code>src/thegent/contracts/registry.py</code></li><li>undefined<strong>CSM schema</strong>: <code>src/thegent/contracts/csm.py</code></li><li>undefined<strong>Adapters</strong>: <code>src/thegent/contracts/adapters.py</code></li><li>undefined<strong>Provider contracts</strong>: <code>docs/contracts/PROVIDER_ADAPTER_CONTRACTS.md</code></li><li>undefined<strong>Usage</strong>: <code>from thegent.contracts import get_registry, CanonicalStructuredMessage, normalize_output</code></li></ul><hr><h2 id="_7-legacy-adapter-g-kd-01" tabindex="-1">7. Legacy Adapter (G-KD-01) <a class="header-anchor" href="#_7-legacy-adapter-g-kd-01" aria-label="Permalink to &quot;7. Legacy Adapter (G-KD-01)&quot;">​</a></h2><p>Legacy or non-XML outputs are handled via:</p><ul><li>undefined<strong>GenericOutputAdapter</strong>: Uses <code>extract_condensed</code> for plain text; sets <code>source_contract=plain</code>, confidence 0.7.</li><li>undefined<strong>Fallback path</strong>: When XML adapter fails or no tags, <code>normalize_output</code> returns CSM with <code>source_contract=fallback-plain</code>, confidence 0.3–0.5.</li><li>undefined<strong>Contract negotiation</strong>: <code>source_contract</code> in CSM identifies origin (xml-tags, plain, fallback-plain). Policy gates may reject fallback-plain for critical lanes.</li></ul><p>All adapters produce CSM with <code>schema_version=&quot;csm-v1&quot;</code>. Legacy outputs are never rejected at parse time; they are normalized and tagged for policy decisions.</p><hr><h2 id="_8-fallback-control-plane" tabindex="-1">8. Fallback Control Plane <a class="header-anchor" href="#_8-fallback-control-plane" aria-label="Permalink to &quot;8. Fallback Control Plane&quot;">​</a></h2><p>See <strong>FALLBACK_POLICY.md</strong> for normalization fallback policy, observability, and guardrails.</p><hr><h2 id="_9-references" tabindex="-1">9. References <a class="header-anchor" href="#_9-references" aria-label="Permalink to &quot;9. References&quot;">​</a></h2><ul><li>Research validation: <code>docs/docset/thegent-research-validation-2026-02-14.md</code></li><li>Cross-analysis: <code>docs/docset/thegent-cross-analysis-matrix-2026-02-14.md</code></li><li>Kush docs: <code>docs/docset/thegent-kush-docs-deep-dive-2026-02-14.md</code></li><li>Gap analysis: <code>docs/docset/thegent-gaps-and-discovery-2026-02-14.md</code></li><li>undefined<strong>Task-tool XML contract (authoritative):</strong> <code>../task-tool/docs/xml_contract.md</code> — aligned with implementation (task_graph root, snake_case tags)</li></ul>',36)])])}const _=e(a,[["render",n]]);export{m as __pageData,_ as default};
